tma_pkg_remove() { for p in "$@"; do
  if command -v dnf >/dev/null 2>&1; then dnf -y remove "$p";
  elif command -v yum >/dev/null 2>&1; then yum -y remove "$p";
  elif command -v apt-get >/dev/null 2>&1; then apt-get -y purge "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n remove "$p"; fi; done; }
tma_pkg_install() { for p in "$@"; do
  if command -v dnf >/dev/null 2>&1; then dnf -y install "$p";
  elif command -v yum >/dev/null 2>&1; then yum -y install "$p";
  elif command -v apt-get >/dev/null 2>&1; then apt-get -y install "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n install "$p"; fi; done; }
tma_svc_off() { for u in "$@"; do systemctl stop "$u" 2>/dev/null; systemctl mask "$u" 2>/dev/null; done; return 0; }
f=/etc/ssh/sshd_config
[ -f "$f" ] || exit 0
k=permituserenvironment; v=no
cp -p "$f" "$f.tmaegis.bak" 2>/dev/null
# the audit and sshd both honour the FIRST occurrence, so drop old lines and put ours first
{ printf '%s %s\n' "$k" "$v"; grep -viE "^[[:space:]]*$k[[:space:]]" "$f.tmaegis.bak"; } > "$f.tma.new" && cat "$f.tma.new" > "$f"
rm -f "$f.tma.new"; true

set -u
export DEBIAN_FRONTEND=noninteractive
tma_pkg_remove() { for p in "$@"; do
  if command -v dnf >/dev/null 2>&1; then dnf -y remove "$p";
  elif command -v yum >/dev/null 2>&1; then yum -y remove "$p";
  elif command -v apt-get >/dev/null 2>&1; then apt-get -y purge "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n remove "$p"; fi; done; }
tma_pkg_install() { for p in "$@"; do
  if command -v dnf >/dev/null 2>&1; then dnf -y install "$p";
  elif command -v yum >/dev/null 2>&1; then yum -y install "$p";
  elif command -v apt-get >/dev/null 2>&1; then apt-get -y install "$p";
  elif command -v zypper >/dev/null 2>&1; then zypper -n install "$p"; fi; done; }
tma_svc_off() { for u in "$@"; do systemctl stop "$u" 2>/dev/null; systemctl mask "$u" 2>/dev/null; done; return 0; }
command -v vim-cmd >/dev/null 2>&1 || exit 0
# Only powered-off VMs: ESXi rewrites the .vmx of running VMs, so edits to those would not stick.
find /vmfs/volumes/ -maxdepth 3 -type f -name '*.vmx' 2>/dev/null | while IFS= read -r f; do
  id=$(vim-cmd vmsvc/getallvms 2>/dev/null | awk -v f="$(basename "$f")" 'index($0,f){print $1; exit}')
  [ -n "$id" ] && ! vim-cmd vmsvc/power.getstate "$id" 2>/dev/null | grep -q 'Powered off' && { echo "skip running VM $f"; continue; }
  cp -p "$f" "$f.tmaegis.bak"
  { grep -viE '^[[:space:]]*migrate[.]encryptionmode[[:space:]]*=' "$f.tmaegis.bak"; printf '%s = "%s"\n' 'migrate.encryptionmode' 'required'; } > "$f.tma.new" && cat "$f.tma.new" > "$f"; rm -f "$f.tma.new"
  [ -n "$id" ] && vim-cmd vmsvc/reload "$id" >/dev/null 2>&1
done; true

